<template>
 <view class="screen focus-screen">
  <view v-if="store.user" class="focus-topline"><text class="eyebrow">FOCUS 沉时</text><button class="secondary small checkin-mini" :disabled="store.busy||store.study.checked_in" @click="checkin">{{store.study.checked_in?(store.study.early_checked_in?'早起打卡 ✓':'日常打卡 ✓'):'为今天打卡'}}</button></view>
  <Scenery title="把时间，留给喜欢的事。" caption="一次只做一件事，也是一种很好的前进。" compact/>
  <AccountGate/>
  <view v-if="store.user">
   <button class="date-peek" @click="goDates"><view class="mini-calendar"><text>期待</text><text>{{nearestDate?Math.abs(dateDays(nearestDate.target_date)):'＋'}}</text></view><view class="grow"><text class="peek-title">{{nearestDate?nearestDate.title:'给期待留一个日期'}}</text><text class="peek-caption">{{nearestDate?(dateDays(nearestDate.target_date)===0?'就是今天，好好迎接它！':dateDays(nearestDate.target_date)>0?'还有 '+dateDays(nearestDate.target_date)+' 天，慢慢靠近':'已走过 '+Math.abs(dateDays(nearestDate.target_date))+' 天'):'在任务里设置你的重要倒计时'}}</text></view><text class="peek-link">查看 ›</text></button>
   <view class="focus-layout">
    <view class="card timer-card">
     <view class="timer-visual"><view class="mode"><button :class="{chosen:mode==='focus'}" :disabled="!!breakEnd" @click="choose('focus')">专注</button><button :class="{chosen:mode==='break'}" :disabled="!!store.session" @click="choose('break')">休息</button></view>
     <view v-if="!store.session&&mode==='focus'" class="segment timer-types"><button :class="{selected:timerMode==='down'}" @click="timerMode='down'">倒计时</button><button :class="{selected:timerMode==='up'}" @click="timerMode='up'">正计时</button></view><view class="circle"><text class="muted">{{hint}}</text><text class="clock">{{clock}}</text><text class="task-name">{{mode==='break'?'让注意力也休息一下':store.session?.task_title||taskNames[taskIndex]||'自由专注'}}</text></view>
     </view><view class="timer-controls"><view v-if="!store.session&&mode==='focus'" class="focus-settings">
      <view v-if="timerMode==='down'" class="preset-row"><button v-for="minutes in [15,25,50]" :key="minutes" :class="{picked:Number(customMinutes)===minutes}" :disabled="store.busy" @click="preset(minutes)">{{minutes}} 分钟</button></view>
      <view v-if="timerMode==='down'" class="custom-duration row between"><view><text class="label">自定义时长</text><text class="section-meta">本次有效 · 1–180 分钟</text></view><view class="row duration-input"><input v-model="customMinutes" aria-label="本次专注分钟数" type="number" maxlength="3" placeholder="25"/><text class="muted">分钟</text></view></view>
      <text v-if="timerMode==='up'" class="muted up-note">从 00:00 开始，按实际专注时间记录。单次最多 24 小时。</text><button class="picker row between task-picker-button" @click="taskOpen=true"><text>专注任务</text><text class="picked-task">{{taskNames[taskIndex]||'自由专注'}} ⌄</text></button><view class="reminder-controls"><text class="label">结束提醒</text><view class="reminder-options"><button v-for="option in reminderOptions" :key="option.value" :class="{chosen:alertKind===option.value}" @click="setReminder(option.value)">{{option.label}}</button><button class="try-reminder" @click="testReminder">试一下</button></view></view><text class="reminder-note">保持页面打开才能及时提醒；锁屏、后台或静音模式可能限制铃声和震动。</text>
     </view>
     <button class="primary space focus-start" :disabled="store.busy" @click="toggle">{{buttonText}}</button>
     <button v-if="store.session&&isUp&&seconds>0" class="secondary space finish-up" :disabled="store.busy" @click="finishUp">结束并保存专注</button><button v-if="store.session" class="text-button cancel-focus" :disabled="store.busy" @click="cancel">放弃本次</button>
     <text class="footnote">{{mode==='break'?'休息不计入专注记录，结束后继续下一次。':store.session?'完成计时后，点击保存即可计入学习记录。':'准备好就开始，过程中可以随时暂停。'}}</text></view>
    </view>
    <button class="sound-entry" @click="soundOpen=true"><CartoonArt kind="cafe" label="专注白噪音"/><view class="grow"><text class="title">白噪音</text><text class="muted">{{soundPlaying?'正在播放 · 点击调整':'为专注选一段喜欢的声音'}}</text></view><text>选择声音 ›</text></button>
   </view>
   <view class="card wish-shortcut"><CartoonArt class="wish-letter" kind="letter" label="星星心愿信封"/><view class="grow"><text class="title">心愿邮局</text><text class="muted">让愿望成为星星，小时陪你慢慢实现。</text></view><button class="secondary small" @click="goWishes">去许愿 →</button></view>
   
   <view class="card room-shortcut"><view class="grow"><text class="title">{{store.room?'正在 '+store.room.name:'想找个学习搭子？'}}</text><text class="muted">{{store.room?store.room.members.length+' 位同学在这里':'和朋友加入同一个自习室，各自专注、彼此陪伴。'}}</text></view><button class="secondary small" @click="goRooms">前往自习室 →</button></view>
  </view>
 </view>
<WarmDialog :open="taskOpen&&pageVisible" title="今天，想专注哪件事？" @close="taskOpen=false"><view class="task-choices"><button v-for="(name,i) in taskNames" :key="i" :class="{chosen:taskIndex===i}" @click="taskIndex=i;taskOpen=false"><CartoonArt :kind="i===0?'sun':'book'" label="专注任务"/><text class="grow">{{name}}</text><text>{{taskIndex===i?'✓':'›'}}</text></button></view></WarmDialog><view v-if="pageVisible" v-show="soundOpen" class="sound-overlay" @click.self="soundOpen=false"><view class="sound-sheet" role="dialog" aria-modal="true" aria-label="白噪音选择" @keydown.esc="soundOpen=false"><view class="row between sheet-heading"><text class="title">给专注加一点声音</text><button class="secondary small" @click="soundOpen=false">收起面板</button></view><scroll-view scroll-y class="sound-scroll"><NoisePlayer :session-state="store.session?.status||''" :expired="!!store.session&&((!isUp&&seconds===0)||(isUp&&seconds>=86400))" @playing-change="soundPlaying=$event"/></scroll-view><text class="sheet-note">收起后继续播放；暂停专注或离开页面时停止。</text></view></view><AppNav current="focus"/></template>
<script setup>
import WarmDialog from '../../components/WarmDialog.vue';
import {prepareReminder,remind,disposeReminder} from '../../services/reminder';
import AppNav from '../../components/AppNav.vue';
import CartoonArt from '../../components/CartoonArt.vue';
import {ref,computed} from 'vue';import NoisePlayer from '../../components/NoisePlayer.vue';import Scenery from '../../components/Scenery.vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import AccountGate from '../../components/AccountGate.vue';import {store,refresh,remaining,act} from '../../services/store';import {confirm,message} from '../../services/api';
const taskOpen=ref(false),timerMode=ref('down'),alertKind=ref('ring');let remindedId=null;const isUp=computed(()=>(store.session?.timer_mode||timerMode.value)==='up');
const soundOpen=ref(false),soundPlaying=ref(false);const pageVisible=ref(false),customMinutes=ref(25);let draftOwner=null,draftDefault=null;
const now=ref(Date.now()),mode=ref('focus'),taskIndex=ref(0),breakEnd=ref(0);let timer;let visible=false;
const pending=computed(()=>store.tasks.filter(t=>!t.completed));const taskNames=computed(()=>['自由专注',...pending.value.map(t=>t.title)]);
const seconds=computed(()=>mode.value==='break'?(breakEnd.value?Math.max(0,Math.ceil((breakEnd.value-now.value)/1000)):store.settings.break_minutes*60):store.session?(isUp.value?store.session.duration-remaining(now.value):remaining(now.value)):timerMode.value==='up'?0:Math.max(0,Number(customMinutes.value)||0)*60);
const clock=computed(()=>`${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`);
const hint=computed(()=>mode.value==='break'?'休息一下，再出发':store.session?((!isUp.value&&seconds.value===0)||seconds.value>=86400?'专注已到时':store.session.status==='paused'?'暂停一下，稍后继续':'专注当下，慢慢来'):'准备好，开始一小步');
const buttonText=computed(()=>mode.value==='break'?(breakEnd.value?'结束休息':'开始休息'):store.session?((!isUp.value&&seconds.value===0)||seconds.value>=86400?'保存本次专注':store.session.status==='paused'?'继续专注':'暂停专注'):'开始专注 →');
const reminderOptions=[{value:'ring',label:'铃声'},{value:'vibrate',label:'震动'},{value:'silent',label:'静音'}];
function setReminder(value){alertKind.value=value;uni.setStorageSync('focus-reminder-'+store.user?.id,value);}
function testReminder(){if(alertKind.value==='ring'){prepareReminder();setTimeout(()=>remind('ring'),150);}else remind(alertKind.value);}
async function finishUp(){const id=store.session?.id;if(!id)return;if(await act('/sessions/complete','POST',{session_id:id})){remind(alertKind.value);mode.value='break';message('本次专注已保存，辛苦啦！');}}
const storageKey=()=>`tomato-break-${store.user?.id}`;
async function checkin(){if(await act('/checkins'))message(store.study.early_checked_in?'早起打卡成功，小时和你一起迎接今天！':'日常打卡成功，今天也有认真前进。');}
const dateDays=value=>Math.round((Date.parse(value)-Date.parse(new Date(now.value+8*3600000).toISOString().slice(0,10)))/86400000);
const nearestDate=computed(()=>[...store.countdowns].filter(d=>dateDays(d.target_date)>=0).sort((a,b)=>a.target_date.localeCompare(b.target_date))[0]||[...store.countdowns].sort((a,b)=>b.target_date.localeCompare(a.target_date))[0]);
function goDates(){uni.setStorageSync('focus-task-section','dates');uni.switchTab({url:'/pages/tasks/index'});}
function preset(minutes){customMinutes.value=minutes;}
function goWishes(){uni.navigateTo({url:'/pages/wishes/index'});}
function goRooms(){uni.switchTab({url:'/pages/rooms/index'});}
function resetBreak(){breakEnd.value=0;uni.removeStorageSync(storageKey());}
function tick(){now.value=Date.now();const s=store.session;if(s&&((!isUp.value&&seconds.value===0)||(isUp.value&&seconds.value>=86400))&&remindedId!==s.id){remindedId=s.id;remind(alertKind.value);message('本次专注已到时，记得保存你的努力。');}if(breakEnd.value&&breakEnd.value<=now.value){resetBreak();message('休息结束，准备下一次专注吧。');}}
onShow(async()=>{visible=true;clearInterval(timer);await refresh();if(!visible)return;pageVisible.value=true;alertKind.value=uni.getStorageSync('focus-reminder-'+store.user?.id)||'ring';if(draftOwner!==store.user?.id){taskIndex.value=0;}if(draftOwner!==store.user?.id||draftDefault!==store.settings.focus_minutes){customMinutes.value=store.settings.focus_minutes;draftDefault=store.settings.focus_minutes;draftOwner=store.user?.id;}const draftKey='tomato-focus-draft-'+store.user?.id;const draft=uni.getStorageSync(draftKey);if(draft){taskIndex.value=Math.max(0,pending.value.findIndex(t=>t.id===draft.taskId)+1);uni.removeStorageSync(draftKey);}if(store.session)mode.value='focus';breakEnd.value=Number(uni.getStorageSync(storageKey()))||0;if(breakEnd.value&&!store.session)mode.value='break';tick();timer=setInterval(tick,500);});onHide(()=>{visible=false;pageVisible.value=false;soundOpen.value=false;taskOpen.value=false;soundPlaying.value=false;clearInterval(timer);});onUnload(()=>{disposeReminder();visible=false;pageVisible.value=false;soundOpen.value=false;taskOpen.value=false;soundPlaying.value=false;clearInterval(timer);});
function choose(value){if(store.session&&value==='break')return message('请先完成或放弃本次专注');if(breakEnd.value&&value==='focus')return message('请先结束休息');mode.value=value;}
async function toggle(){if(mode.value==='break'){if(breakEnd.value)resetBreak();else{breakEnd.value=Date.now()+store.settings.break_minutes*60000;uni.setStorageSync(storageKey(),breakEnd.value);}return;}
 const s=store.session;if(!s){const minutes=Number(customMinutes.value);if(timerMode.value==='down'&&(!Number.isInteger(minutes)||minutes<1||minutes>180))return message('本次专注请输入 1–180 的整数分钟');resetBreak();if(alertKind.value==='ring')prepareReminder();await act('/sessions','POST',{task_id:pending.value[taskIndex.value-1]?.id??null,focus_minutes:minutes,timer_mode:timerMode.value});}
 else{const action=((!isUp.value&&seconds.value===0)||(isUp.value&&seconds.value>=86400))?'complete':s.status==='running'?'pause':'resume';if(await act('/sessions/'+action,'POST',{session_id:s.id})){if(action==='complete'){mode.value='break';message('本次专注已保存，辛苦啦！');}}}tick();}
async function cancel(){if(await confirm('放弃本次专注？本次不会计入完成统计。'))await act('/sessions/cancel','POST',{session_id:store.session.id});}
</script>
<style scoped>.timer-card{text-align:center}.mode{display:flex;justify-content:center;gap:10rpx;background:#f7f0e2;border-radius:40rpx;margin:10rpx 80rpx 40rpx;padding:8rpx}.mode text{padding:14rpx 35rpx;color:#ab9067;font-size:26rpx}.mode .chosen{background:#fff;border-radius:35rpx;color:#8d734f}.circle{width:410rpx;height:410rpx;max-width:100%;border:7rpx solid #f7f0e2;border-top-color:#ccb58a;border-right-color:#e9dcc1;border-radius:50%;margin:20rpx auto 30rpx;display:flex;flex-direction:column;align-items:center;justify-content:center}.clock{font-size:106rpx;font-weight:500;letter-spacing:-5rpx;margin:18rpx 0}.task-name{font-size:25rpx;color:#ab9067;max-width:340rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.picker{background:#fffcf6;padding:22rpx;border-radius:18rpx;font-size:25rpx;color:#8d734f}.custom-duration{text-align:left;background:#fffcf6;border:2rpx solid #f7f0e2;border-radius:22rpx;padding:22rpx;margin-bottom:24rpx}.custom-duration input{width:150rpx;margin:10rpx 0;height:75rpx;font-size:32rpx}.custom-duration .section-meta{display:block;font-size:20rpx}.date-peek{display:flex;align-items:center;gap:20rpx;width:100%;text-align:left;background:#fff7dc;border:2rpx solid #e8d39e;padding:18rpx 24rpx;margin-bottom:24rpx;color:#75562c}.mini-calendar{width:66rpx;background:#fffef7;border:2rpx solid #ddbd76;border-radius:12rpx;text-align:center;overflow:hidden;transform:rotate(-5deg);flex-shrink:0}.mini-calendar text{display:block;font-size:26rpx;font-weight:700}.mini-calendar text:first-child{background:#f1cb71;font-size:17rpx;padding:3rpx}.peek-title{display:block;font-size:25rpx;font-weight:650;overflow-wrap:anywhere}.peek-caption{display:block;font-size:21rpx;color:#96784d;margin-top:4rpx}.peek-link{font-size:22rpx;flex-shrink:0}</style>
<style scoped>
.mode{margin:0 auto 32rpx;max-width:360rpx;gap:4rpx}.mode button{flex:1;background:transparent;color:#725b40;font-size:26rpx;padding:14rpx 24rpx;border-radius:30rpx}.mode button.chosen{background:#fff;color:#5a4934;box-shadow:0 2rpx 8rpx #5a493412}.custom-duration{padding:16rpx 20rpx;background:#fffcf6;margin-bottom:16rpx}.custom-duration .label{font-size:25rpx}.custom-duration .duration-input{gap:10rpx;flex-shrink:0}.custom-duration input{width:108rpx;height:76rpx;margin:0;text-align:center;font-size:30rpx;padding:10rpx}.picker{font-size:24rpx;text-align:left}.picked-task{max-width:65%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cancel-focus{margin:12rpx auto 0}.timer-card .footnote{margin-top:20rpx}.focus-start{width:100%}.wish-shortcut{display:flex;align-items:center;gap:20rpx;background:#edf3e8}.wish-shortcut .title{margin-bottom:10rpx}.room-shortcut{display:flex;align-items:center;gap:24rpx}.room-shortcut .title{margin-bottom:12rpx}.room-shortcut button{flex-shrink:0}.sound-card{align-self:start}
</style>
<style scoped>
.focus-topline{display:flex;align-items:center;justify-content:space-between;margin-bottom:18rpx}.focus-topline .eyebrow{margin:0}.checkin-mini{font-size:22rpx;padding:12rpx 20rpx;min-height:64rpx}.focus-layout{display:block;max-width:760rpx;margin:0 auto}.sound-entry{display:flex;text-align:left;align-items:center;gap:20rpx;width:100%;background:#fff5d8;color:#80602d;border:2rpx solid #ead5a2;margin-bottom:28rpx;padding:20rpx 24rpx}.sound-entry .cartoon-art{width:72rpx;height:72rpx}.sound-entry .title{margin-bottom:5rpx;font-size:27rpx}.sound-entry>text{font-size:23rpx;flex-shrink:0}.sound-entry .muted{font-size:23rpx}.sound-overlay{position:fixed;inset:0;z-index:300;background:#3c2c1e66;display:flex;align-items:center;justify-content:center;padding:24rpx}.sound-sheet{width:100%;max-width:820rpx;background:#fffdf6;border:2rpx solid #e6d1a5;border-radius:30rpx;padding:26rpx;box-sizing:border-box;box-shadow:0 25rpx 90rpx #402d2833}.sheet-heading{margin-bottom:20rpx}.sheet-heading .title{font-size:28rpx}.sound-scroll{height:60vh}.sheet-note{display:block;padding-top:20rpx;color:#806c4e;font-size:22rpx}.focus-screen{max-width:850px}
</style>
<style scoped>.timer-types{max-width:460rpx;margin:0 auto 24rpx}.task-picker-button{width:100%;border:2rpx solid #ecd8aa}.task-choices button{display:flex;align-items:center;gap:20rpx;width:100%;text-align:left;background:#fff5d9;color:#79582c;margin-bottom:14rpx;border:2rpx solid #ecdbb4;padding:20rpx}.task-choices button.chosen{background:#ffe9a7;border-color:#d5af5a}.task-choices .cartoon-art{width:60rpx;height:60rpx}.task-choices .grow{overflow-wrap:anywhere}.reminder-controls{margin-top:24rpx;text-align:left}.reminder-options{display:flex;gap:10rpx;flex-wrap:wrap;margin-top:12rpx}.reminder-options button{background:#faf0d9;color:#8b6c3f;padding:12rpx 20rpx;font-size:23rpx}.reminder-options .chosen{background:#f2d388;border:2rpx solid #dbb263}.reminder-options .try-reminder{margin-left:auto;background:#fff9eb}.reminder-note{display:block;color:#a18a63;font-size:20rpx;text-align:left;line-height:1.6;margin-top:12rpx}.up-note{padding:0 0 22rpx}.finish-up{width:100%}</style>

